"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["3775"],{7849(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>h,frontMatter:()=>a,contentTitle:()=>c,toc:()=>d,assets:()=>s});var o=JSON.parse('{"id":"reference/register/howtos/configure-FXT-GL-AirPrime-ForAV","title":"How to configure my AirPrime module for AirVantage?","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV","permalink":"/personal-av-docs/docs/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to configure my AirPrime module for AirVantage?","sidebar_label":"How to configure my AirPrime module for ","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV","format":"md"}}'),r=t(4848),i=t(8453);let a={title:"How to configure my AirPrime module for AirVantage?",sidebar_label:"How to configure my AirPrime module for ",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV",format:"md"},c,s={},d=[];function u(e){let n={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(n.p,{children:[":::note Edition\n",(0,r.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(n.a,{href:"https://doc.airvantage.net/av/reference/register/howtos/configure-FXT-GL-AirPrime-ForAV",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsx)(n.p,{children:"How to configure my AirPrime module for AirVantage?\nConfigure your embedded module\nBefore you register your AirPrime module in AirVantage you need to check it has been configure to communicate. Please note that this procedure is also valid for AirLink programmable modems (GL and FX series).\nThe module can be configured to communicate periodically with AirVantage using the AT command\nAT+WDSC=3,xx\n(xx in minutes). This is the heartbeat period.\nIf you need to trigger a connection before the next heartbeat period, then you can use the AT command\nAT+WDSS=1,1\n.\nThe communication with AirVantage is using TCP/IP. By default, the module gets its IP address from the APN configured with the command\nAT+CGDCONT=1,\u201CIP\u201D,\u201Ccarrierapn\u201D\nAs an option, if you want to use a dedicated APN for module monitoring traffic, you can configure it using the\nAT+WDSS=0,\u201Cmy apn\u201D\n.\nIf you don\u2019t need to use a dedicated APN for device monitoring traffic, the module will retrieve the first valid APN configured in the records set with AT+CGDCONT command.\nRegister your AirPrime module or AirLink FX and GL\nTo register an AirPrime module, an FXT009, FX100 or a GL you need to provide the Serial number and the IMEI.\nYou can get the serial number of the module with the command\nAT+WMSN\n.\nYou can get the IMEI of the module with the command\nAT+WIMEI?\n.\nModule connection troubleshooting\nFew errors can occur during the device communication with AirVantage. The rootcause can be understood using local device indications.\nYou may need to configure the device to get local indication with command AT+WDSI=8191.\nIn the examples given, the device will initiate the connexion to the server (Polling mode).\nOptionnally configure the APN (at+wdss=0) according to the sim card you are using\nIf you don\u2019t need to use a dedicated APN for device monitoring traffic, the module will retrieve automatically the first valid APN configured in the records set with AT+CGDCONT command. You can jump to next section.\nExample:\nAT+WDSS=0,\u201Capn-name\u201D, \u201Clogin\u201D,\u201Cpwd\u201D\nTo check the current configuration\nAT+WDSS?\n+WDSS: 0,\u201Capn-name\u201D,\u201Clogin\u201D,\u201Cpwd\u201D\n+WDSS: 1,0\nInitiate a connection to AirVantage\nTo initiate your first connection to the server, your device should be already registered on the server.\nAT+WDSS=1,1\n+WDSI: 4\n+WDSI: 6\n+WDSI: 8\nAt this point, your device connect, managed authentication and execute the job pending on the server.\nThe first connection after registration, AirVantage synchronizes the system.\nDuring furture connections if there is no job to execute on the server for the module the sequence will be:\n+WDSI: 4\n+WDSI: 8\nIf the notifications from the module are different, check the AT command Reference guide or look at the next sections in this page.\nDevice can not get an internet connexion with the network : GPRS error or APN error\nIf the device indication is:\n+WDSI: 7\nThis is an issue with the 2G/3G connection or with the APN setting.\nCheck the SIM can attach to GPRS network.\nAT+CGATT?\n+CGATT: 1\nAT+CGREG?\n+CGREG: 1\nIf you don\u2019t manage to get these answers, you should try with a valid sim card\nOnce this is Ok, you may need to double check the APN configured. If it still fails, then try to test with another APN or Sim card.\nDevice is not registered on the server\nIf the device indications are:\n+WDSI: 4\n+WDSI: 7\nYour device seems not correctly registered on the server: you may want to check the device identifier: IMEI.\nDevice can not be authenticated\nIf the device indications are:\n+WDSI: 4\n+WDSI: 5\nYour device is not accepted by the server.\nCan be due to an error on the serial number registered in the server.\nPin activation status\nBefore all check of your device, your sim card shall be inserted in the device and PIN code validated or deactivated.\nAT+CPIN?\n+CPIN: READY\nIf the answer is different, please check your sim card or validate your PIN:\nAT+CPIN=xxxx\n."})]})}function h(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>c});var o=t(6540);let r={},i=o.createContext(r);function a(e){let n=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function c(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);